185	+  for (size_t pos = cfg_text.find(kKey); pos != std::string::npos;
186	+       pos = cfg_text.find(kKey, pos + 1)) {
187	+    const size_t start = pos + sizeof(kKey) - 1;
188	+    const size_t end = cfg_text.find('"', start);
