1	// Oracle differential compare. See state_diff.hpp for the policy.
2	#include "state_diff.hpp"
3	
4	#include <cstdio>
5	#include <string>
6	#include <string_view>
7	
8	namespace andes_sim {
9	
10	namespace {
11	
12	void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
13	         unsigned long long got) {
14	  ++r.compared;
15	  if (ref != got) r.diffs.push_back({field, ref, got});
16	}
17	
18	}  // namespace
19	
20	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
21	                       const std::vector<std::string>& andes_supported) {
22	  DiffReport r;
23	
24	  cmp(r, "magic", ref.magic, got.magic);
25	  cmp(r, "version", ref.version, got.version);
26	  cmp(r, "flags", ref.flags, got.flags);
27	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
28	  cmp(r, "priv", ref.priv, got.priv);
29	  cmp(r, "pc", ref.pc, got.pc);
30	
31	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
32	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
33	  // implementation-defined / carry dirty bits (false positives).
34	  cmp(r, "mepc", ref.mepc, got.mepc);
35	  cmp(r, "mcause", ref.mcause, got.mcause);
36	
37	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
38	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
39	  // them. mip is excluded: its pending bits are hardware/platform-driven
40	  // (timer/external) and diverge between QEMU's functional clock and vsim's
41	  // cycle clock even with no trap (it still round-trips into the drained
42	  // record, just not the verifier).
43	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
44	  cmp(r, "mtval", ref.mtval, got.mtval);
45	  cmp(r, "mie", ref.mie, got.mie);
46	
47	  // S/U trap CSRs (ax66 registration, option A): on an S-mode engine whose
48	  // --describe names them they round-trip (restored at resume, re-read at
49	  // drain), so the verifier compares them. Gated on the EXPLICIT name: an
50	  // empty list (no engine info) or an M-only engine keeps the passthrough
51	  // skip -- unlike the X-macro blocks, empty does NOT mean compare-all here,
52	  // because M-only engines never restore these.
53	  auto named_supported = [&](std::string_view name) {
54	    for (const std::string& s : andes_supported)
55	      if (s == name) return true;
56	    return false;
57	  };
58	  if (named_supported("satp"))    cmp(r, "satp",    ref.satp,    got.satp);
59	  if (named_supported("medeleg")) cmp(r, "medeleg", ref.medeleg, got.medeleg);
60	  if (named_supported("mideleg")) cmp(r, "mideleg", ref.mideleg, got.mideleg);
61	
62	  for (int i = 0; i < 32; ++i)
63	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
64	
65	  if (ref.flags & HYBRID_FLAG_FP) {
66	    for (int i = 0; i < 32; ++i)
67	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
68	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
69	  }
70	
71	  if (ref.flags & HYBRID_FLAG_V) {
72	    cmp(r, "vstart", ref.vstart, got.vstart);
73	    cmp(r, "vtype", ref.vtype, got.vtype);
74	    cmp(r, "vl", ref.vl, got.vl);
75	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
76	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
77	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
78	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
79	
80	    // One compared "field" per vector register; report the first differing
81	    // byte as "v<i>[<byte>]".
82	    for (int i = 0; i < 32; ++i) {
83	      ++r.compared;
84	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
85	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
86	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
87	        if (a[j] != b[j]) {
88	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
89	                                 std::to_string(j) + "]",
90	                             a[j], b[j]});
91	          break;
92	        }
93	      }
94	    }
95	  }
96	
97	  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
98	  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
99	  // restores them, StateDrain re-reads them), so a correct transport matches the
100	  // oracle. The X-macro is the single source of truth shared with the plugin
101	  // drain / resume / drain re-read, so this list can never drift out of sync.
102	  //
103	  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
104	  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
105	  // protection drains 0. That divergence is an engine-implementation artifact,
106	  // not a transport bug (the restore is a tolerant no-op on a core lacking the
107	  // CSR) -- so they are transported but excluded from strict verify, exactly
108	  // like mip's hardware-driven pending bits.
109	  auto andes_verify_excluded = [](std::string_view name) {
110	    // msp_bound/msp_base: engine-reset-divergent HW stack-protection bounds.
111	    // milmb/mdlmb: ILM/DLM base+enable CSRs. The base address round-trips, but
112	    // the enable bit (bit 0) is HW-presence state -- the vsim RTL has the local
113	    // memories and drains EN=1, while QEMU models none and drains EN=0. Same
114	    // class as msp_bound/msp_base (an engine-implementation artifact, not a
115	    // transport bug), so excluded rather than half-compared via a bit mask.
116	    // mhpmcounter3..6: hardware performance counters that increment DURING the
117	    // ROI, so the vsim (cycle) and QEMU (functional) values legitimately differ
118	    // -- transported and restored, but not strict-compared, like mcycle/mip.
119	    // mdcause: vsim models it as HW-set (a direct write drains back 0).
120	    // tdata1/tcontrol/mcontext: debug-trigger state whose reset defaults and
121	    // WARL widths differ between QEMU and vsim. All transported + restored, but
122	    // not cross-engine strict-compared.
123	    // mnvec: QEMU resets it to 0; the Andes RTL resets it to the hart's reset
124	    // vector and WARL-holds it (a restore write of 0 does not take), so a
125	    // trap-free ROI always false-diffs. Seen live on both engines when the
126	    // registration audit first claimed it (spec: "IM Requirement: Required").
127	    static constexpr std::string_view kExcluded[] = {
128	        "msp_bound", "msp_base", "milmb", "mdlmb",
129	        "mhpmcounter3", "mhpmcounter4", "mhpmcounter5", "mhpmcounter6",
130	        "mdcause", "tdata1", "tcontrol", "mcontext", "mnvec"};
131	    for (std::string_view e : kExcluded)
132	      if (e == name) return true;
133	    return false;
134	  };
135	  // Engine capability gate (S4): skip any Andes CSR the cycle engine does not
136	  // implement. Empty list = no engine info -> compare all (back-compat).
137	  auto andes_supported_csr = [&](std::string_view name) {
138	    if (andes_supported.empty()) return true;
139	    for (const std::string& s : andes_supported)
140	      if (s == name) return true;
141	    return false;
142	  };
143	  // v6 write-mask gate: skip any mask-governed CSR the program never WROTE
144	  // (per the oracle's mask, which covers boot + ROI). Unwritten CSRs hold
145	  // QEMU's reset default in `ref` but the engine's own RTL reset in `got`
146	  // (the restore skipped them too), so comparing would false-positive on
147	  // every reset-value divergence. Flag clear = pre-v6 file = compare all.
148	  auto wm_live = [&](int slot) {
149	    if (!(ref.flags & HYBRID_FLAG_WRITE_MASK)) return true;
150	    return hybrid_wm_test(ref.write_mask, static_cast<unsigned>(slot)) != 0;
151	  };
152	  if (ref.flags & HYBRID_FLAG_ANDES) {
153	#define X(field, addr, name)                                     \
154	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
155	      && wm_live(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)) \
156	    cmp(r, name, ref.andes.field, got.andes.field);
157	    HYBRID_ANDES_CSR_LIST(X)
158	#undef X
159	    if (andes_supported_csr("pmacfg"))
160	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
161	        if (wm_live(HYBRID_WM_PMACFG_BASE + i))
162	          cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
163	              got.andes.pmacfg[i]);
164	    if (andes_supported_csr("pmaaddr"))
165	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
166	        if (wm_live(HYBRID_WM_PMAADDR_BASE + i))
167	          cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
168	              got.andes.pmaaddr[i]);
169	  }
170	
171	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
172	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
173	  // is neither restored, drained, nor compared.
174	  if (ref.flags & HYBRID_FLAG_M_EXT) {
175	#define X(field, addr, name)                                     \
176	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
177	      && wm_live(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)) \
178	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
179	    HYBRID_M_EXT_CSR_LIST(X)
180	#undef X
181	  }
182	
183	  // L2C MMIO config (v5): the L2C Control Register round-trips (restored at
184	  // resume, re-read at drain), so compare its RW config bits (CEN, prefetch,
185	  // ECC, RAM timing). INITSTATUS[14] is a read-only status bit -- a real L2C
186	  // model drives it, QEMU's RAM stub does not -- so mask it to avoid a false
187	  // positive. Only the writable Control Register is verified; the read-only
188	  // Configuration Register and the volatile CCTL/error/counter registers are
189	  // captured but not restored, so they are not compared.
190	  if (ref.flags & HYBRID_FLAG_L2C) {
191	    const uint64_t rw_mask = ~(uint64_t{1} << 14);  // clear INITSTATUS[14]
192	    cmp(r, "l2c.ctrl",
193	        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask,
194	        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask);
195	  }
196	
197	  return r;
198	}
199	
200	std::vector<std::string> unsupported_written_csrs(
201	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported) {
202	  std::vector<std::string> out;
203	  if (!(st.flags & HYBRID_FLAG_WRITE_MASK)) return out;  // pre-v6: no info
204	  if (andes_supported.empty()) return out;               // no engine info
205	
206	  const auto supported = [&](std::string_view name) {
207	    for (const std::string& s : andes_supported)
208	      if (s == name) return true;
209	    return false;
210	  };
211	  const auto written = [&](int slot) {
212	    return hybrid_wm_test(st.write_mask, static_cast<unsigned>(slot)) != 0;
213	  };
214	
215	  // Andes scalars. ucode is skipped: the plugin sets its bit unconditionally
216	  // (transport-always DSP flag), so it carries no real write information.
217	#define X(field, addr, name)                                              \
218	  if (std::string_view{name} != "ucode"                                   \
219	      && written(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)      \
220	      && !supported(name))                                                \
221	    out.push_back(name);
222	  HYBRID_ANDES_CSR_LIST(X)
223	#undef X
224	
225	  // PMA: one group marker each, matching the --describe list's convention.
226	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
227	    if (written(HYBRID_WM_PMACFG_BASE + i) && !supported("pmacfg")) {
228	      out.push_back("pmacfg");
229	      break;
230	    }
231	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
232	    if (written(HYBRID_WM_PMAADDR_BASE + i) && !supported("pmaaddr")) {
233	      out.push_back("pmaaddr");
234	      break;
235	    }
236	
237	#define X(field, addr, name)                                              \
238	  if (written(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)         \
239	      && !supported(name))                                                \
240	    out.push_back(name);
241	  HYBRID_M_EXT_CSR_LIST(X)
242	#undef X
243	
244	  return out;
245	}
246	
247	std::string unsupported_written_warning(
248	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
249	    const std::string& engine_id) {
250	  const auto bad = unsupported_written_csrs(st, andes_supported);
251	  if (bad.empty()) return {};
252	  std::string names;
253	  for (const std::string& n : bad) {
254	    if (!names.empty()) names += ", ";
255	    names += n;
256	  }
257	  return "[andesim] warning: the program wrote CSRs engine " + engine_id +
258	         " does not implement: " + names +
259	         " (on this engine's silicon these writes would trap; the hybrid "
260	         "restore skipped them)\n";
261	}
262	
263	void print_diff_report(const DiffReport& r) {
264	  for (const FieldDiff& d : r.diffs)
265	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
266	                d.ref, d.got);
267	  if (r.ok()) {
268	    std::printf(
269	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
270	        "excluded)\n",
271	        r.compared);
272	  } else {
273	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
274	                r.diffs.size(), r.compared);
275	  }
276	}
277	
278	}  // namespace andes_sim
